import os
import json
import requests
import subprocess
import sys
import time

def load_config(config_path):
    with open(config_path, 'r') as f:
        return json.load(f)

def fetch_pending_jobs(api_base_url, token):
    headers = {'Authorization': f'Bearer {token}'}
    response = requests.get(f'{api_base_url}/jobs?status=pending', headers=headers)
    response.raise_for_status()
    return response.json().get('jobs', [])

def run_command(command, working_dir, timeout_seconds):
    try:
        result = subprocess.run(command, shell=True, cwd=working_dir, capture_output=True, text=True, timeout=timeout_seconds)
        return result.returncode, result.stdout, result.stderr, False
    except subprocess.TimeoutExpired as e:
        return None, e.stdout, e.stderr, True

def report_result(api_base_url, job_id, exit_code, stdout, stderr, timed_out, token):
    headers = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json'
    }
    data = {
        'exit_code': exit_code,
        'stdout': stdout,
        'stderr': stderr,
        'timed_out': timed_out
    }
    response = requests.post(f'{api_base_url}/jobs/{job_id}/result', headers=headers, json=data)
    response.raise_for_status()

def main(config_path):
    config = load_config(config_path)
    api_base_url = config['api_base_url']
    token = os.getenv(config['token_env_var'])
    working_dir = config['working_dir']
    timeout_seconds = config['timeout_seconds']

    jobs = fetch_pending_jobs(api_base_url, token)
    for job in jobs:
        job_id = job['id']
        command = job['command']
        exit_code, stdout, stderr, timed_out = run_command(command, working_dir, timeout_seconds)
        if timed_out:
            exit_code = None
        report_result(api_base_url, job_id, exit_code, stdout, stderr, timed_out, token)
        print(f'{job_id} {exit_code if exit_code is not None else "timeout"}')  

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print('Usage: python jobrunner.py <config.json>')
        sys.exit(1)
    main(sys.argv[1])
